package com.careerpilot.backend.modules.application.services;
import com.careerpilot.backend.modules.application.domain.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class EligibilityEngine { public record Request(double matchScore,double minimumScore,List<String> mandatorySkills,List<String> candidateSkills,double requiredExperience,double candidateExperience,boolean educationMet,boolean workAuthorized,boolean locationMatched,boolean remoteMatched,boolean duplicate,boolean preferencesMet){} public record Result(EligibilityDecision decision,List<String> reasons){} public Result evaluate(Request r){List<String> reasons=new ArrayList<>();if(r.duplicate())reasons.add("Duplicate application");if(r.matchScore()<r.minimumScore())reasons.add("Match score below threshold");if(!lower(r.candidateSkills()).containsAll(lower(r.mandatorySkills())))reasons.add("Mandatory skills missing");if(r.candidateExperience()<r.requiredExperience())reasons.add("Required experience not met");if(!r.workAuthorized())reasons.add("Work authorization not met");if(!r.educationMet())reasons.add("Education requirement not met");if(!r.preferencesMet())reasons.add("User preferences not met");if(reasons.stream().anyMatch(x->x.equals("Duplicate application")||x.equals("Work authorization not met")))return new Result(EligibilityDecision.NOT_ELIGIBLE,reasons);if(!reasons.isEmpty()||!r.locationMatched()||!r.remoteMatched()){if(!r.locationMatched())reasons.add("Location requires review");if(!r.remoteMatched())reasons.add("Remote preference requires review");return new Result(EligibilityDecision.REQUIRES_REVIEW,reasons);}return new Result(EligibilityDecision.ELIGIBLE,List.of());}private Set<String> lower(List<String>x){Set<String>s=new HashSet<>();if(x!=null)x.forEach(v->s.add(v.toLowerCase(Locale.ROOT)));return s;} }
